import{_ as r,a}from"./chunks/qgc_airframe.CdjUQBTE.js";import{_ as i}from"./chunks/Vectored6DofUUV.DjL-SuZ8.js";import{_ as l}from"./chunks/rc_mode2_mc_position_mode.Bg2XhzFf.js";import{_ as n,C as s,o as d,c,j as e,a as h,E as u,al as m}from"./chunks/framework.7vp1BMOE.js";const M=JSON.parse('{"title":"BlueROV2 (UUV)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/frames_sub/bluerov2.md","filePath":"ko/frames_sub/bluerov2.md"}'),p={name:"ko/frames_sub/bluerov2.md"};function g(f,t,b,k,v,w){const o=s("Badge");return d(),c("div",null,[t[0]||(t[0]=e("h1",{id:"bluerov2-uuv",tabindex:"-1"},[h("BlueROV2 (UUV) "),e("a",{class:"header-anchor",href:"#bluerov2-uuv","aria-label":'Permalink to "BlueROV2 (UUV)"'},"​")],-1)),u(o,{type:"tip",text:"PX4 v1.12"}),t[1]||(t[1]=m('<p>The <a href="https://bluerobotics.com/store/rov/bluerov2/" target="_blank" rel="noreferrer">BlueROV2</a> is an affordable high-performance underwater vehicle that is perfect for inspections, research, and adventuring.</p><p>PX4 provides <a href="./">experimental support</a> for an 8-thrust vectored configuration, known as the <em>BlueROV2 Heavy Configuration</em>.</p><p><img src="'+r+'" alt="Hero"></p><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><p><a href="https://bluerobotics.com/store/rov/bluerov2/" target="_blank" rel="noreferrer">BlueROV2</a> + <a href="https://bluerobotics.com/store/rov/bluerov2-accessories/brov2-heavy-kit/" target="_blank" rel="noreferrer">BlueROV2 Heavy Configuration Retrofit Kit</a></p><h3 id="모터-매핑과-배선" tabindex="-1">모터 매핑과 배선 <a class="header-anchor" href="#모터-매핑과-배선" aria-label="Permalink to &quot;모터 매핑과 배선&quot;">​</a></h3><p>The motors must be wired to the flight controller following the standard instructions supplied by BlueRobotics for this vehicle .</p><p>The vehicle will then match the configuration documented in the <a href="./../airframes/airframe_reference#vectored-6-dof-uuv">Airframe Reference</a>:</p><img src="'+i+'" width="29%" style="max-height:180px;"><ul><li><strong>MAIN1:</strong> motor 1 CCW, bow starboard horizontal, , propeller CCW</li><li><strong>MAIN2:</strong> motor 2 CCW, bow port horizontal, propeller CCW</li><li><strong>MAIN3:</strong> motor 3 CCW, stern starboard horizontal, propeller CW</li><li><strong>MAIN4:</strong> motor 4 CCW, stern port horizontal, propeller CW</li><li><strong>MAIN5:</strong> motor 5 CCW, bow starboard vertical, propeller CCW</li><li><strong>MAIN6:</strong> motor 6 CCW, bow port vertical, propeller CW</li><li><strong>MAIN7:</strong> motor 7 CCW, stern starboard vertical, propeller CW</li><li><strong>MAIN8:</strong> motor 8 CCW, stern port vertical, propeller CCW</li></ul><h2 id="basic-control-axes" tabindex="-1">Basic Control Axes <a class="header-anchor" href="#basic-control-axes" aria-label="Permalink to &quot;Basic Control Axes&quot;">​</a></h2><p>For underwater vehicles, motion is defined in terms of body axes:</p><ul><li><strong>Surge:</strong> forward/back motion - translation along the body X axis.</li><li><strong>Sway:</strong> left/right motion - translation along the body Y axis.</li><li><strong>Heave:</strong> up/down motion - translation along the body Z axis.</li><li><strong>Yaw:</strong> rotation about the (vertical) body Z axis.</li></ul><h3 id="stick-mapping-mode-2" tabindex="-1">Stick Mapping (Mode 2) <a class="header-anchor" href="#stick-mapping-mode-2" aria-label="Permalink to &quot;Stick Mapping (Mode 2)&quot;">​</a></h3><p>The mapping below illustrates the default joystick behavior:</p><ul><li><strong>Pitch stick (forward/back):</strong> surge</li><li><strong>Roll stick (left/right):</strong> sway</li><li><strong>Throttle stick (up/down):</strong> heave</li><li><strong>Yaw stick (left/right):</strong> yaw</li></ul><p><img src="'+l+'" alt="RC Basic Commands"></p><h2 id="manual-modes" tabindex="-1">Manual Modes <a class="header-anchor" href="#manual-modes" aria-label="Permalink to &quot;Manual Modes&quot;">​</a></h2><p>The following manual and assisted modes are currently supported on BlueROV2 Heavy:</p><table tabindex="0"><thead><tr><th>Mode</th><th>설명</th></tr></thead><tbody><tr><td>Manual</td><td>Direct manual control of thrust and yaw.</td></tr><tr><td>Stabilized</td><td>Manual control of thurst and yaw with roll/pitch stabilization.</td></tr><tr><td>Acro</td><td>Manual control of yaw-rate and direct thrust commands with roll/pitch stabilization.</td></tr><tr><td>Altitude</td><td>Manual control of x/y thrust and yaw. Control of height with PID, manually controlled by user. Keeps roll/pitch stabilized.</td></tr><tr><td>Position</td><td>Controls x, y, z and yaw with position hold when sticks are released. Keeps roll/pitch stabilized.</td></tr></tbody></table><h2 id="joystick-stick-mode" tabindex="-1">Joystick Stick Mode <a class="header-anchor" href="#joystick-stick-mode" aria-label="Permalink to &quot;Joystick Stick Mode&quot;">​</a></h2><p>BlueROV2 supports two joystick mappings for manual control, selected using the <a href="./../advanced_config/parameter_reference#UUV_STICK_MODE">UUV_STICK_MODE</a> parameter.</p><p>By default, <code>UUV_STICK_MODE</code> is set to <code>0</code>, which enables the UUV stick mapping intended for vectored underwater vehicles.</p><h3 id="uuv-stick-mode-0-default" tabindex="-1">UUV_STICK_MODE = 0 (default) <a class="header-anchor" href="#uuv-stick-mode-0-default" aria-label="Permalink to &quot;UUV_STICK_MODE = 0 (default)&quot;">​</a></h3><p>This mode is intended for normal BlueROV2 operation. In <code>Manual</code>, <code>Stabilized</code>, and <code>Acro</code> modes, the sticks command:</p><ul><li><strong>Pitch stick:</strong> surge - moving stick up -&gt; moving forward, +X translation in body frame.</li><li><strong>Roll stick:</strong> sway - moving stick right -&gt; moving sideways right, +Y translation in body frame.</li><li><strong>Throttle stick:</strong> heave - moving stick up -&gt; moving upwards, -Z translation in body frame (note the Z axis points Down of the vehicle in PX4).</li><li><strong>Yaw stick:</strong> yaw - moving stick right -&gt; yawing to the right, +Z rotation in body frame.</li></ul><p>In this mode, roll and pitch are kept level rather than commanded directly.</p><h3 id="uuv-stick-mode-1" tabindex="-1">UUV_STICK_MODE = 1 <a class="header-anchor" href="#uuv-stick-mode-1" aria-label="Permalink to &quot;UUV_STICK_MODE = 1&quot;">​</a></h3><p>This mode enables the legacy multicopter-style stick mapping for <code>Manual</code>, <code>Stabilized</code>, and <code>Acro</code> modes:</p><ul><li><strong>Throttle stick:</strong> surge - moving stick up -&gt; moving forward, +X translation in body frame.</li><li><strong>Roll stick:</strong> roll - moving stick right -&gt; rolling to the right side, +X rotation in body frame.</li><li><strong>Pitch stick:</strong> pitch - moving stick up -&gt; pitching down, -X translation in body frame (note signs are switched to follow PX4 standard).</li><li><strong>Yaw stick:</strong> yaw - moving stick right -&gt; yawing to the right, +Z rotation in body frame.</li></ul><p>This mode is mainly provided for compatibility with older setups and user preference.</p><h2 id="기체-설정" tabindex="-1">기체 설정 <a class="header-anchor" href="#기체-설정" aria-label="Permalink to &quot;기체 설정&quot;">​</a></h2><p>BlueROV2 does not come with PX4 installed. You will need to:</p><ol><li><a href="./../config/firmware#installing-px4-main-beta-or-custom-firmware">Install PX4 Firmware</a></li><li><a href="./../config/airframe">Set the Airframe</a>. You will need to select the &quot;BlueROV2 Heavy Configuration&quot; as shown: <img src="'+a+'" alt="QGC - select airframe for BlueROV2 Heay configuration"></li></ol><h2 id="비디오" tabindex="-1">비디오 <a class="header-anchor" href="#비디오" aria-label="Permalink to &quot;비디오&quot;">​</a></h2>',35)),t[2]||(t[2]=e("lite-youtube",{videoid:"1sUaURmlmT8",title:"PX4 on BlueRov Demo"},null,-1))])}const V=n(p,[["render",g]]);export{M as __pageData,V as default};
